import{z as A,x as d,o as n,c as B,q as i,j as o,D as t,d as e,s,S as E,b as r}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"阵列乘法","description":"","frontmatter":{"title":"阵列乘法","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/array-multiplier.md","filePath":"cs/array-multiplier.md","lastUpdated":1791063341000}'),p={name:"cs/array-multiplier.md"};function c(m,a,u,D,h,C){const l=d("Mermaid");return n(),B("div",null,[a[2]||(a[2]=i('<h1 id="阵列乘法" tabindex="-1">阵列乘法 <a class="header-anchor" href="#阵列乘法" aria-label="Permalink to &quot;阵列乘法&quot;">​</a></h1><div class="epigraph"><p>乘法是部分积再相加；阵列把每一位乘与一排加法器铺在平面上，延迟随字长涨，不再假装「一次 ALU 就完」。</p><footer>—— 据 Harris and Harris, Digital Design and Computer Architecture；Patterson and Hennessy, Computer Organization and Design (RISC-V) 整理</footer></div><p>上一课<a href="/cs/carry-select">进位选择</a>把加法器的延迟–面积档次说清。本课不重画 CLA，也不从 Booth 编码史另起。缺口是：<a href="/cs/adder-cla">加法器课</a>明确把乘法排除在外。整数乘是重复加或<strong>部分积阵列</strong>，关键路径比一次加长得多。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>无符号：\\(p=\\sum_i a_i b\\cdot 2^i\\)。每一位 \\(a_i\\) 决定是否把 \\(b\\) 左移 \\(i\\) 位加入。缺口是电路：移位是接线，与是部分积，再把 \\(n\\) 个 \\(n\\) 位数加起来。行波阵列：每一行一个加法器，延迟 \\(\\Theta(n^2)\\) 门级；用进位保留（CSA）可把加法树变浅，本课点到，不把华莱士树画完。</p><p>有符号补码乘要符号扩展或 Booth，本课以无符号钉结构。RV32M 的 <code>mul</code> 在组成课可当独立单元，不必塞进单周期同一 \\(T\\)。</p><h3 id="阵列不是「alu-再循环-拍」的同一张图" tabindex="-1">阵列不是「ALU 再循环 \\(n\\) 拍」的同一张图 <a class="header-anchor" href="#阵列不是「alu-再循环-拍」的同一张图" aria-label="Permalink to &quot;阵列不是「ALU 再循环 $n$ 拍」的同一张图&quot;">​</a></h3><p>多周期可以用 ALU 移位加，CPI 为 \\(\\Theta(n)\\)。阵列是组合（或一拍组合）硬件，面积换时间。把两种实现混成一种「乘法器」，后课单周期图会误把 <code>mul</code> 画进与 <code>add</code> 同深的框。</p><p><span class="marginnote">Harris 用阵列与树形压缩。Patterson/Hennessy 把乘除放到整数乘除单元或慢路径。本课不讲浮点对阶乘法。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>部分积：\\(pp_{i,j}=a_i\\land b_j\\)，按权对齐。阵列：第 \\(i\\) 行把 \\(pp_{i,*}\\) 加到部分和上。输出 \\(2n\\) 位。关键路径沿最右进位再向下行，或沿 CSA+末级 CLA。</p><p><span class="marginnote">「部分积」就是「用一个乘数的某一位去逐位与另一个乘数相与得到的一行中间结果」——回想手算多位十进制乘法时，先用个位数乘出一行、再用十位数乘出一行，最后错位相加，那几行就是部分积，二进制只是把「乘一位」换成了一个与门。</span></p>',12)),(n(),o(E,null,{default:t(()=>[s(l,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20AB%5B%22A%20%E4%B8%8E%20B%22%5D%20--%3E%20PP%5B%22%E9%83%A8%E5%88%86%E7%A7%AF%E4%B8%8E%E9%97%A8%E9%98%B5%E5%88%97%22%5D%0A%20%20PP%20--%3E%20ADD%5B%22%E8%A1%8C%E6%B3%A2%E6%88%96%20CSA%20%E5%8E%8B%E7%BC%A9%22%5D%0A%20%20ADD%20--%3E%20PROD%5B%222n%20%E4%BD%8D%E7%A7%AF%22%5D%0A%20%20PROD%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E7%A7%BB%E4%BD%8D%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[e("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,[e("后课 ALU 数据通路默认不含全宽乘；"),r("code",null,"mul"),e(" 另口或另拍。移位下一课单独成块，因为 "),r("code",null,"sll"),e(" 是 ISA 常客，比乘浅。本课只承认：乘的组合深度通常大于加，关键路径分析必须分开。")],-1)),a[5]||(a[5]=r("p",null,"同一次乘法，硬件上有两条实现路线，取舍正好相反：",-1)),(n(),o(E,null,{default:t(()=>[s(l,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E5%90%8C%E4%B8%80%E6%AC%A1%20n%20%E4%BD%8D%E4%B9%98%E6%B3%95%22%5D%20--%3E%20P1%5B%22%E8%B7%AF%E7%BA%BF%E4%B8%80%EF%BC%9A%E5%A4%9A%E5%91%A8%E6%9C%9F%E7%A7%BB%E4%BD%8D%E5%8A%A0%22%5D%0A%20%20Q%20--%3E%20P2%5B%22%E8%B7%AF%E7%BA%BF%E4%BA%8C%EF%BC%9A%E7%BB%84%E5%90%88%E9%98%B5%E5%88%97%22%5D%0A%20%20P1%20--%3E%20R1%5B%22%E5%A4%8D%E7%94%A8%201%20%E4%B8%AA%E5%8A%A0%E6%B3%95%E5%99%A8%E5%BE%AA%E7%8E%AF%20n%20%E6%8B%8D%EF%BC%8C%E9%9D%A2%E7%A7%AF%E5%B0%8F%22%5D%0A%20%20P2%20--%3E%20R2%5B%22%E9%93%BA%20n%20%E8%A1%8C%E4%B8%8E%E9%97%A8%E5%8A%A0%E6%B3%95%E5%99%A8%EF%BC%8C1%20%E6%8B%8D%E5%87%BA%E7%BB%93%E6%9E%9C%EF%BC%8C%E9%9D%A2%E7%A7%AF%E5%A4%A7%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=i('<p><span class="marginnote">给 \\(\\Theta(n^2)\\) 一个数：\\(n=4\\) 时阵列约 4 行加法器、关键路径十几级门；\\(n=64\\) 时按同一比例涨到上千级门，一级门不到百皮秒也架不住串这么多——所以真实 CPU 常把乘法划进慢路径、拆成多拍完成，而不是让它拖住整个主频。</span></p><p><span class="marginnote">常见误区：初学者容易以为「一条 <code>mul</code> 指令就是一个周期」。实际上组合乘法器路径深，很多实现把它放进独立单元或多拍慢路径——这正是本课坚持不把 <code>mul</code> 画进与 <code>add</code> 同深的单周期框的原因。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不实现除法恢复/不恢复、不讲 DSP 块。不把矩阵乘、MAC 阵列提前到体系结构课以外。</p><p>后课默认：整数乘是部分积再加，延迟远大于一次 CLA；教学 CPU 可以没有组合乘法器。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>乘 = 部分积 + 多操作数加。</li><li>阵列面积大、路径长；多周期移位加是另一实现。</li><li>有符号与 Booth 不在本课展开。</li><li>出处：Harris and Harris；Patterson and Hennessy, COD (RISC-V)。</li></ul>',7))])}const f=A(p,[["render",c]]);export{P as __pageData,f as default};
